postCommand(reader) {
  this._reader = reader;
  if (this.closing) {
    this.closing = false;
    reader.closeSocket();
  }
  if (this._startTLSPending) {
    this._startTLSPending = false;
    this._tlsActive = true;
    reader.startTLS();
  }
  if (this.sendingLiteral) {
    reader.preventLFMunge();
  }
  reader.setMultiline(this._multiline);
  if (this._lastCommand == reader.watchWord) {
    reader.stopTest();
  }
}

get idling() {
  return this._idling;
}

sendUnsolicited(response) {
  if (!this._reader?.isRunning) {
    throw new Error("IMAP connection is not running");
  }
  this._reader.send(response);
}
